/**
 * Integration tests: the campus data routes against a real local Supabase.
 *
 * These need `npx supabase start`, `npx supabase db reset` (loads seed.sql),
 * and server/.env. When Supabase is not reachable, test/supabaseProbe.js sets
 * SUPABASE_AVAILABLE to '0' and every test here is skipped.
 *
 * Database ids are generated by Postgres, so the tests look ids up by name
 * instead of hard-coding them.
 */
const request = require('supertest');
const app = require('./app');

const describeWithDatabase = process.env.SUPABASE_AVAILABLE === '1' ? describe : describe.skip;

describeWithDatabase('campus data routes (local Supabase)', () => {
  let buildings;
  let hiemengaId;
  let hekmanId;

  beforeAll(async () => {
    const res = await request(app).get('/api/v1/buildings');
    buildings = res.body;
    hiemengaId = buildings.find((b) => b.name === 'Hiemenga Hall')?.id;
    hekmanId = buildings.find((b) => b.name === 'Hekman Library')?.id;
  });

  describe('GET /api/v1/buildings', () => {
    it('returns the seeded buildings as { id, name }', () => {
      expect(buildings.length).toBeGreaterThan(0);
      expect(buildings.map((b) => b.name)).toEqual(
        expect.arrayContaining(['Science Building', 'Hekman Library', 'Hiemenga Hall'])
      );
      for (const building of buildings) {
        expect(Object.keys(building).sort()).toEqual(['id', 'name']);
        expect(typeof building.id).toBe('number');
      }
    });
  });

  describe('GET /api/v1/buildings/:id', () => {
    it('returns one building with sorted floors and labelled rooms', async () => {
      const res = await request(app).get(`/api/v1/buildings/${hiemengaId}`);
      expect(res.status).toBe(200);
      expect(res.body).toMatchObject({ id: hiemengaId, code: 'HH', name: 'Hiemenga Hall' });
      expect(res.body).not.toHaveProperty('isParkingLot');

      const levels = res.body.floors.map((floor) => floor.level);
      expect(levels).toEqual([...levels].sort((a, b) => a - b));

      const level2 = res.body.floors.find((floor) => floor.level === 2);
      expect(level2.label).toBe('Level 2');
      expect(level2.rooms).toEqual(expect.arrayContaining(['HH 211', 'HH 213']));
    });

    it('returns 404 for an id with no building', async () => {
      const res = await request(app).get('/api/v1/buildings/999999');
      expect(res.status).toBe(404);
      expect(res.body).toEqual({ error: 'Building not found' });
    });
  });

  describe('GET /api/v1/points-of-interest', () => {
    it('returns every point of interest in the API shape', async () => {
      const res = await request(app).get('/api/v1/points-of-interest');
      expect(res.status).toBe(200);
      expect(res.body.length).toBeGreaterThan(1);
      for (const point of res.body) {
        expect(Object.keys(point).sort()).toEqual(['buildingId', 'floor', 'id', 'label', 'type']);
      }
    });

    it('filters by type', async () => {
      const res = await request(app).get('/api/v1/points-of-interest?type=printer');
      expect(res.status).toBe(200);
      expect(res.body.length).toBeGreaterThan(0);
      expect(res.body.every((p) => p.type === 'printer')).toBe(true);
      expect(res.body[0].buildingId).toBe(hekmanId);
    });

    it('accepts a type with a space or an underscore and answers with a space', async () => {
      const spaced = await request(app).get('/api/v1/points-of-interest?type=water%20fountain');
      const underscored = await request(app).get('/api/v1/points-of-interest?type=WATER_FOUNTAIN');
      expect(spaced.body.length).toBeGreaterThan(0);
      expect(underscored.body).toEqual(spaced.body);
      expect(spaced.body.every((p) => p.type === 'water fountain')).toBe(true);
    });
  });

  describe('GET /api/v1/search', () => {
    it('finds a building by partial name', async () => {
      const res = await request(app).get('/api/v1/search?q=hekman');
      expect(res.status).toBe(200);
      expect(res.body).toContainEqual({ kind: 'building', id: hekmanId, name: 'Hekman Library' });
    });

    it('finds a room and labels it with building code and number', async () => {
      const res = await request(app).get('/api/v1/search?q=hh-211');
      expect(res.status).toBe(200);
      expect(res.body).toContainEqual({ kind: 'room', buildingId: hiemengaId, floor: 2, name: 'HH 211' });
    });

    it('finds a point of interest by type or label', async () => {
      const res = await request(app).get('/api/v1/search?q=printer');
      expect(res.status).toBe(200);
      expect(res.body).toEqual(
        expect.arrayContaining([expect.objectContaining({ kind: 'poi', name: 'Printer' })])
      );
    });

    it('matches case-insensitively', async () => {
      const lower = await request(app).get('/api/v1/search?q=hekman library');
      const upper = await request(app).get('/api/v1/search?q=HEKMAN LIBRARY');
      expect(upper.status).toBe(200);
      expect(upper.body).toEqual(lower.body);
      expect(upper.body).toContainEqual({ kind: 'building', id: hekmanId, name: 'Hekman Library' });
    });

    it('returns an empty list when nothing matches', async () => {
      const res = await request(app).get('/api/v1/search?q=zzz');
      expect(res.status).toBe(200);
      expect(res.body).toEqual([]);
    });
  });
});
